<script setup lang="ts">
import { ref, computed } from 'vue'
import { api } from '../api'
import { usePage, perform, busy } from '../state'
import { requestKey, positiveDecimal } from '../domain'
import type { Row } from '../domain'
import PageHeader from '../components/PageHeader.vue'
import DataTable from '../components/DataTable.vue'
import LoadState from '../components/LoadState.vue'
const plans=ref<Row[]>([]),runs=ref<Row[]>([]),cards=ref<Row[]>([]),funds=ref<Row[]>([]),open=ref(false),editing=ref<Row|null>(null),form=ref<Row>({}),key=ref(requestKey())
const {loading,error,load}=usePage(async()=>{[plans.value,runs.value,cards.value,funds.value]=await Promise.all([api.get('/sip-plans'),api.get('/sip-runs'),api.get('/bank-cards'),api.get('/funds')])})
const activeCards=computed(()=>cards.value.filter(c=>c.status==='ACTIVE'))
function create(plan?:Row){editing.value=plan||null;form.value={fundClassId:plan?.fundClassId||funds.value[0]?.id||'',tradingAccountId:plan?.tradingAccountId||activeCards.value.find(c=>c.isDefault)?.tradingAccountId||activeCards.value[0]?.tradingAccountId||'',amount:plan?.amount||'100.00',frequency:plan?.frequency||'MONTHLY',day:plan?.day||1,startDate:plan?.startDate||'2026-10-12'};key.value=requestKey();open.value=true}
async function save(){await perform(async()=>{if(!positiveDecimal(form.value.amount))throw new Error('定投金额需大于零、最多两位小数');const card=activeCards.value.find(c=>c.tradingAccountId===Number(form.value.tradingAccountId));if(!card)throw new Error('请选择可扣款交易账户');const payload={...form.value,fundClassId:Number(form.value.fundClassId),tradingAccountId:card.tradingAccountId,bankCardId:card.id,bindingVersion:card.bindingVersion,day:Number(form.value.day),requestKey:key.value};return editing.value?api.patch('/sip-plans/'+editing.value.id,payload):api.post('/sip-plans',payload)},async()=>{open.value=false;await load()})}
async function status(plan:Row,state:string){await perform(()=>api.patch('/sip-plans/'+plan.id,{status:state}),load)}
</script>
<template><PageHeader title="定投计划" subtitle="固定来源账户，按周或月执行，暂停与终止只影响未来期次。"><button class="button primary" @click="create()">＋ 创建计划</button><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><section class="panel"><h2>我的计划</h2><DataTable :rows="plans" :columns="[{key:'id',label:'计划'}, {key:'fundName',label:'基金'}, {key:'tradingAccountId',label:'扣款账户'}, {key:'amount',label:'每期金额（元）',kind:'money'}, {key:'frequency',label:'频率'}, {key:'day',label:'星期/日期'}, {key:'startDate',label:'起始日期'}, {key:'status',label:'状态',kind:'state'}]"><template #actions="{row}"><template v-if="row.status!=='TERMINATED'"><button class="text-button" @click="create(row)">修改</button><button class="text-button" :disabled="busy>0" @click="status(row,row.status==='ACTIVE'?'PAUSED':'ACTIVE')">{{ row.status==='ACTIVE'?'暂停':'恢复' }}</button><button class="text-button danger" :disabled="busy>0" @click="status(row,'TERMINATED')">终止</button></template></template></DataTable></section><section class="panel"><h2>执行记录</h2><DataTable :rows="runs" :columns="[{key:'planId',label:'计划'}, {key:'scheduledDate',label:'原计划日期'}, {key:'executionDate',label:'实际执行日'}, {key:'orderId',label:'生成订单'}, {key:'status',label:'结果',kind:'state'}, {key:'reason',label:'原因'}]"/></section><p class="notice">非开放日顺延至下一开放日。余额不足仅记录当期失败，不自动补扣。暂停计划仍属于未终止业务，会阻止账户解绑。</p><el-dialog v-model="open" :title="editing?'修改未来定投参数':'新建定投计划'" width="590px"><form class="form-grid" @submit.prevent="save"><label><span>基金</span><select v-model="form.fundClassId" required :disabled="!!editing"><option v-for="f in funds.filter(f=>f.purchaseOpen&&f.state==='OPEN')" :key="f.id" :value="f.id">{{ f.name }}</option></select></label><label><span>固定扣款交易账户</span><select v-model="form.tradingAccountId" required><option v-for="c in activeCards" :key="c.id" :value="c.tradingAccountId">{{ c.bankName }} · {{ c.accountNo }}</option></select></label><label><span>每期金额（元）</span><input v-model="form.amount" required inputmode="decimal"/></label><label><span>周期</span><select v-model="form.frequency" :disabled="!!editing"><option value="WEEKLY">每周</option><option value="MONTHLY">每月</option></select></label><label><span>{{ form.frequency==='WEEKLY'?'星期（1=周一）':'每月日期（1至28）' }}</span><input v-model="form.day" type="number" min="1" :max="form.frequency==='WEEKLY'?7:28" required/></label><label><span>开始日期</span><input v-model="form.startDate" type="date" required :disabled="!!editing"/></label><div class="wide"><button class="button primary" :disabled="busy>0">保存计划</button></div></form></el-dialog></template>
